function _direction_shift(direction::Integer)
    if direction == 0 || abs(direction) > 4
        throw(ArgumentError("shift direction must be one of -4:-1 or 1:4, received $direction"))
    end

    sign = ifelse(direction > 0, Int64(1), Int64(-1))
    axis = abs(direction)
    shift = if axis == 1
        (sign, Int64(0), Int64(0), Int64(0))
    elseif axis == 2
        (Int64(0), sign, Int64(0), Int64(0))
    elseif axis == 3
        (Int64(0), Int64(0), sign, Int64(0))
    else
        (Int64(0), Int64(0), Int64(0), sign)
    end
    return shift
end

