using Random

function _matrix_determinant(matrix::AbstractMatrix, nc::Integer)
    if nc == 2
        return matrix[1, 1] * matrix[2, 2] - matrix[1, 2] * matrix[2, 1]
    elseif nc == 3
        return matrix[1, 1] * (matrix[2, 2] * matrix[3, 3] - matrix[2, 3] * matrix[3, 2]) -
               matrix[1, 2] * (matrix[2, 1] * matrix[3, 3] - matrix[2, 3] * matrix[3, 1]) +
               matrix[1, 3] * (matrix[2, 1] * matrix[3, 2] - matrix[2, 2] * matrix[3, 1])
    end
    throw(ArgumentError("matrix color count must be 2 or 3, received $nc"))
end

function _require_color_matrix(matrix::AbstractMatrix)
    rows, columns = size(matrix)
    if rows != columns || (rows != 2 && rows != 3)
        throw(DimensionMismatch("color matrix must have shape 2×2 or 3×3"))
    end
    return rows
end

function normalizeN!(matrix::AbstractMatrix)
    nc = _require_color_matrix(matrix)
    for column in 1:nc
        for previous in 1:(column - 1)
            projection = 0.0 + 0.0im
            for row in 1:nc
                projection += conj(matrix[row, previous]) * matrix[row, column]
            end
            for row in 1:nc
                matrix[row, column] -= projection * matrix[row, previous]
            end
        end

        norm_squared = 0.0
        for row in 1:nc
            norm_squared += abs2(matrix[row, column])
        end
        if norm_squared <= 1.0e-28
            throw(ArgumentError("matrix columns are linearly dependent"))
        end
        inverse_norm = inv(sqrt(norm_squared))
        for row in 1:nc
            matrix[row, column] *= inverse_norm
        end
    end

    determinant = _matrix_determinant(matrix, nc)
    determinant_magnitude = abs(determinant)
    if determinant_magnitude <= 1.0e-14
        throw(ArgumentError("matrix determinant is numerically zero"))
    end
    phase_correction = conj(determinant) / determinant_magnitude
    for row in 1:nc
        matrix[row, 1] *= phase_correction
    end
    return matrix
end

normalize2!(matrix::AbstractMatrix) = normalizeN!(matrix)
normalize3!(matrix::AbstractMatrix) = normalizeN!(matrix)

function _standard_normal_pair()
    first_uniform = rand()
    while first_uniform <= 0.0
        first_uniform = rand()
    end
    radius = sqrt(-2.0 * log(first_uniform))
    angle = 2.0 * pi * rand()
    return radius * cos(angle), radius * sin(angle)
end

function _haar_su_matrix!(matrix::AbstractMatrix)
    nc = _require_color_matrix(matrix)
    for column in 1:nc
        for row in 1:nc
            real_part, imaginary_part = _standard_normal_pair()
            matrix[row, column] = ComplexF64(real_part, imaginary_part)
        end
    end
    normalizeN!(matrix)
    return matrix
end

function normalize_U!(field::Gaugefields_4D_nowing)
    matrix = zeros(ComplexF64, field.NC, field.NC)
    for t in 1:field.NT
        for z in 1:field.NZ
            for y in 1:field.NY
                for x in 1:field.NX
                    for j in 1:field.NC
                        for i in 1:field.NC
                            matrix[i, j] = field[i, j, x, y, z, t]
                        end
                    end
                    normalizeN!(matrix)
                    for j in 1:field.NC
                        for i in 1:field.NC
                            field[i, j, x, y, z, t] = matrix[i, j]
                        end
                    end
                end
            end
        end
    end
    return field
end

