function randomGaugefields_4D_nowing(
    NC,
    NX,
    NY,
    NZ,
    NT;
    verbose_level=0,
    randomnumber="Random",
    seed=nothing,
)
    if !(verbose_level isa Integer)
        throw(ArgumentError("verbose_level must be an integer"))
    end
    random_mode = String(randomnumber)
    if random_mode != "Random" && random_mode != "Reproducible"
        throw(ArgumentError("randomnumber must be \"Random\" or \"Reproducible\""))
    end
    if seed !== nothing
        if !(seed isa Integer)
            throw(ArgumentError("seed must be an integer or nothing"))
        end
        Random.seed!(seed)
    elseif random_mode == "Reproducible"
        Random.seed!(123)
    end

    field = Gaugefields_4D_nowing(NC, NX, NY, NZ, NT)
    matrix = zeros(ComplexF64, field.NC, field.NC)
    for t in 1:field.NT
        for z in 1:field.NZ
            for y in 1:field.NY
                for x in 1:field.NX
                    _haar_su_matrix!(matrix)
                    for j in 1:field.NC
                        for i in 1:field.NC
                            field[i, j, x, y, z, t] = matrix[i, j]
                        end
                    end
                end
            end
        end
    end
    return field
end

