function _validate_serial_options(
    mpi,
    PEs,
    mpiinit,
    cuda,
    blocks,
    accelerator,
    singleprecision,
    isMPILattice,
    boundarycondition,
)
    if mpi != false || PEs !== nothing || (mpiinit !== nothing && mpiinit != false)
        throw(ArgumentError("GaugefieldsLite supports serial execution only"))
    end
    if cuda != false || blocks !== nothing || !(accelerator == "none" || accelerator == :none)
        throw(ArgumentError("GaugefieldsLite does not support accelerator options"))
    end
    if singleprecision != false || isMPILattice != false
        throw(ArgumentError("GaugefieldsLite supports ComplexF64 serial fields only"))
    end
    if boundarycondition !== nothing
        if length(boundarycondition) != 4
            throw(ArgumentError("boundarycondition must contain four entries"))
        end
        for value in boundarycondition
            if value != 1
                throw(ArgumentError("GaugefieldsLite currently supports periodic boundaries only"))
            end
        end
    end
    return nothing
end

function Initialize_Gaugefields(
    NC,
    NDW,
    NN...;
    condition="cold",
    mpi=false,
    PEs=nothing,
    mpiinit=nothing,
    verbose_level=0,
    randomnumber="Random",
    cuda=false,
    blocks=nothing,
    accelerator="none",
    singleprecision=false,
    isMPILattice=false,
    boundarycondition=nothing,
    seed=nothing,
)
    _validated_ndw(NDW)
    if length(NN) != 4
        throw(ArgumentError("GaugefieldsLite supports exactly four lattice dimensions"))
    end
    _validate_serial_options(
        mpi,
        PEs,
        mpiinit,
        cuda,
        blocks,
        accelerator,
        singleprecision,
        isMPILattice,
        boundarycondition,
    )

    condition_name = lowercase(String(condition))
    if condition_name != "cold" && condition_name != "hot" && condition_name != "random"
        throw(ArgumentError("condition must be \"cold\", \"hot\", or \"random\""))
    end
    random_mode = String(randomnumber)
    if random_mode != "Random" && random_mode != "Reproducible"
        throw(ArgumentError("randomnumber must be \"Random\" or \"Reproducible\""))
    end
    if seed !== nothing && !(seed isa Integer)
        throw(ArgumentError("seed must be an integer or nothing"))
    end

    if condition_name != "cold"
        if seed !== nothing
            Random.seed!(seed)
        elseif random_mode == "Reproducible"
            Random.seed!(123)
        end
    end

    prototype = Gaugefields_4D_nowing(NC, NN...)
    fields = Vector{typeof(prototype)}(undef, 4)
    for direction in 1:4
        if condition_name == "cold"
            fields[direction] = identityGaugefields_4D_nowing(
                NC,
                NN...;
                verbose_level=verbose_level,
            )
        else
            fields[direction] = randomGaugefields_4D_nowing(
                NC,
                NN...;
                verbose_level=verbose_level,
                randomnumber="Random",
            )
        end
    end
    return fields
end

function Initialize_4DGaugefields(NC, NDW, NN...; kwargs...)
    if length(NN) != 4
        throw(ArgumentError("Initialize_4DGaugefields requires four lattice extents"))
    end
    return Initialize_Gaugefields(NC, NDW, NN...; kwargs...)
end
