function _require_configuration(fields::Vector)
    if length(fields) != 4
        throw(DimensionMismatch("a four-dimensional configuration must contain four link fields"))
    end
    reference = fields[1]
    if !(reference isa Gaugefields_4D_nowing)
        throw(ArgumentError("configuration entries must be Gaugefields_4D_nowing fields"))
    end
    for direction in 2:4
        field = fields[direction]
        if !(field isa Gaugefields_4D_nowing) || size(field) != size(reference)
            throw(DimensionMismatch("all four link fields must have the same color and lattice shape"))
        end
    end
    return reference
end

function _shifted_coordinates(x, y, z, t, direction::Integer, step::Integer, reference)
    if direction == 1
        x = _periodic_coordinate(x, step, reference.NX)
    elseif direction == 2
        y = _periodic_coordinate(y, step, reference.NY)
    elseif direction == 3
        z = _periodic_coordinate(z, step, reference.NZ)
    elseif direction == 4
        t = _periodic_coordinate(t, step, reference.NT)
    else
        throw(ArgumentError("direction must be in 1:4"))
    end
    return x, y, z, t
end

function _plaquette_site_generic_unchecked(fields, reference, mu, nu, x, y, z, t)
    xmu, ymu, zmu, tmu = _shifted_coordinates(x, y, z, t, mu, 1, reference)
    xnu, ynu, znu, tnu = _shifted_coordinates(x, y, z, t, nu, 1, reference)

    total = 0.0 + 0.0im
    for i in 1:reference.NC
        for j in 1:reference.NC
            first = fields[mu][i, j, x, y, z, t]
            for k in 1:reference.NC
                second = fields[nu][j, k, xmu, ymu, zmu, tmu]
                for l in 1:reference.NC
                    third = conj(fields[mu][l, k, xnu, ynu, znu, tnu])
                    fourth = conj(fields[nu][i, l, x, y, z, t])
                    total += first * second * third * fourth
                end
            end
        end
    end
    return total
end

function _plaquette_site_su2_unchecked(fields, reference, mu, nu, x, y, z, t)
    xmu, ymu, zmu, tmu = _shifted_coordinates(x, y, z, t, mu, 1, reference)
    xnu, ynu, znu, tnu = _shifted_coordinates(x, y, z, t, nu, 1, reference)

    a11 = fields[mu][1, 1, x, y, z, t]
    a12 = fields[mu][1, 2, x, y, z, t]
    a21 = fields[mu][2, 1, x, y, z, t]
    a22 = fields[mu][2, 2, x, y, z, t]
    b11 = fields[nu][1, 1, xmu, ymu, zmu, tmu]
    b12 = fields[nu][1, 2, xmu, ymu, zmu, tmu]
    b21 = fields[nu][2, 1, xmu, ymu, zmu, tmu]
    b22 = fields[nu][2, 2, xmu, ymu, zmu, tmu]
    c11 = fields[mu][1, 1, xnu, ynu, znu, tnu]
    c12 = fields[mu][1, 2, xnu, ynu, znu, tnu]
    c21 = fields[mu][2, 1, xnu, ynu, znu, tnu]
    c22 = fields[mu][2, 2, xnu, ynu, znu, tnu]
    d11 = fields[nu][1, 1, x, y, z, t]
    d12 = fields[nu][1, 2, x, y, z, t]
    d21 = fields[nu][2, 1, x, y, z, t]
    d22 = fields[nu][2, 2, x, y, z, t]

    ab11 = a11 * b11 + a12 * b21
    ab12 = a11 * b12 + a12 * b22
    ab21 = a21 * b11 + a22 * b21
    ab22 = a21 * b12 + a22 * b22
    dc11 = d11 * c11 + d12 * c21
    dc12 = d11 * c12 + d12 * c22
    dc21 = d21 * c11 + d22 * c21
    dc22 = d21 * c12 + d22 * c22
    return ab11 * conj(dc11) + ab12 * conj(dc12) +
           ab21 * conj(dc21) + ab22 * conj(dc22)
end

function _plaquette_site_unchecked(fields, reference, mu, nu, x, y, z, t)
    if reference.NC == 2
        return _plaquette_site_su2_unchecked(fields, reference, mu, nu, x, y, z, t)
    end
    return _plaquette_site_generic_unchecked(fields, reference, mu, nu, x, y, z, t)
end

function plaquette_site(fields::Vector, mu::Integer, nu::Integer, x, y, z, t)
    reference = _require_configuration(fields)
    if mu < 1 || mu > 4 || nu < 1 || nu > 4 || mu == nu
        throw(ArgumentError("plaquette directions must be distinct values in 1:4"))
    end
    return _plaquette_site_unchecked(fields, reference, mu, nu, x, y, z, t)
end

function forward_staple_site!(
    output::AbstractMatrix,
    fields::Vector,
    mu::Integer,
    nu::Integer,
    x,
    y,
    z,
    t,
)
    reference = _require_configuration(fields)
    if mu == nu || mu < 1 || mu > 4 || nu < 1 || nu > 4
        throw(ArgumentError("staple directions must be distinct values in 1:4"))
    end
    if size(output) != (reference.NC, reference.NC)
        throw(DimensionMismatch("staple output has the wrong color shape"))
    end
    xmu, ymu, zmu, tmu = _shifted_coordinates(x, y, z, t, mu, 1, reference)
    xnu, ynu, znu, tnu = _shifted_coordinates(x, y, z, t, nu, 1, reference)
    for j in 1:reference.NC
        for i in 1:reference.NC
            value = 0.0 + 0.0im
            for k in 1:reference.NC
                for l in 1:reference.NC
                    value += fields[nu][i, k, xmu, ymu, zmu, tmu] *
                             conj(fields[mu][l, k, xnu, ynu, znu, tnu]) *
                             conj(fields[nu][j, l, x, y, z, t])
                end
            end
            output[i, j] = value
        end
    end
    return output
end

function backward_staple_site!(
    output::AbstractMatrix,
    fields::Vector,
    mu::Integer,
    nu::Integer,
    x,
    y,
    z,
    t,
)
    reference = _require_configuration(fields)
    if mu == nu || mu < 1 || mu > 4 || nu < 1 || nu > 4
        throw(ArgumentError("staple directions must be distinct values in 1:4"))
    end
    if size(output) != (reference.NC, reference.NC)
        throw(DimensionMismatch("staple output has the wrong color shape"))
    end
    xminusnu, yminusnu, zminusnu, tminusnu =
        _shifted_coordinates(x, y, z, t, nu, -1, reference)
    xmunu, ymunu, zmunu, tmunu =
        _shifted_coordinates(xminusnu, yminusnu, zminusnu, tminusnu, mu, 1, reference)
    for j in 1:reference.NC
        for i in 1:reference.NC
            value = 0.0 + 0.0im
            for k in 1:reference.NC
                for l in 1:reference.NC
                    value += conj(fields[nu][k, i, xmunu, ymunu, zmunu, tmunu]) *
                             conj(fields[mu][l, k, xminusnu, yminusnu, zminusnu, tminusnu]) *
                             fields[nu][l, j, xminusnu, yminusnu, zminusnu, tminusnu]
                end
            end
            output[i, j] = value
        end
    end
    return output
end

function construct_staple!(
    staple::Gaugefields_4D_nowing,
    fields::Vector,
    mu::Integer,
    temporary::Gaugefields_4D_nowing,
)
    reference = _require_configuration(fields)
    if mu < 1 || mu > 4
        throw(ArgumentError("staple direction must be in 1:4"))
    end
    _require_compatible_fields(staple, reference)
    _require_compatible_fields(temporary, reference)
    first_term = true
    for nu in 1:4
        if nu == mu
            continue
        end
        mul!(temporary, fields[nu], shift_U(fields[mu], nu))
        beta = ifelse(first_term, 0, 1)
        mul!(staple, temporary, shift_U(fields[nu], mu)', 1, beta)
        first_term = false
    end
    return staple
end

function calculate_Plaquette(
    fields::Vector,
    temporary::Gaugefields_4D_nowing,
    staple::Gaugefields_4D_nowing,
)
    reference = _require_configuration(fields)
    _require_compatible_fields(temporary, reference)
    _require_compatible_fields(staple, reference)
    total = 0.0
    for mu in 1:4
        construct_staple!(staple, fields, mu, temporary)
        mul!(temporary, fields[mu], staple')
        total += real(tr(temporary))
    end
    return 0.5 * total
end

function calculate_Plaquette(fields::Vector, temporaries::Vector)
    if length(temporaries) < 2
        throw(ArgumentError("calculate_Plaquette requires at least two temporary fields"))
    end
    return calculate_Plaquette(fields, temporaries[1], temporaries[2])
end

function calculate_Plaquette(fields::Vector)
    reference = _require_configuration(fields)
    total = 0.0
    for t in 1:reference.NT
        for z in 1:reference.NZ
            for y in 1:reference.NY
                for x in 1:reference.NX
                    for mu in 1:3
                        for nu in (mu + 1):4
                            total += real(
                                _plaquette_site_unchecked(
                                    fields,
                                    reference,
                                    mu,
                                    nu,
                                    x,
                                    y,
                                    z,
                                    t,
                                ),
                            )
                        end
                    end
                end
            end
        end
    end
    return total
end

function normalized_plaquette(fields::Vector)
    reference = _require_configuration(fields)
    return calculate_Plaquette(fields) / (6.0 * reference.NV * reference.NC)
end

function gauge_transform!(destination::Vector, fields::Vector, transformation::Gaugefields_4D_nowing)
    reference = _require_configuration(fields)
    _require_configuration(destination)
    _require_compatible_fields(transformation, reference)
    for direction in 1:4
        _require_compatible_fields(destination[direction], reference)
        if destination[direction] === fields[direction]
            throw(ArgumentError("gauge_transform! destination must not alias the source"))
        end
        for t in 1:reference.NT
            for z in 1:reference.NZ
                for y in 1:reference.NY
                    for x in 1:reference.NX
                        xs, ys, zs, ts =
                            _shifted_coordinates(x, y, z, t, direction, 1, reference)
                        for j in 1:reference.NC
                            for i in 1:reference.NC
                                value = 0.0 + 0.0im
                                for k in 1:reference.NC
                                    for l in 1:reference.NC
                                        value += transformation[i, k, x, y, z, t] *
                                                 fields[direction][k, l, x, y, z, t] *
                                                 conj(transformation[j, l, xs, ys, zs, ts])
                                    end
                                end
                                destination[direction][i, j, x, y, z, t] = value
                            end
                        end
                    end
                end
            end
        end
    end
    return destination
end

function calculate_Polyakov_loop(
    fields::Vector,
    temporary1::Gaugefields_4D_nowing,
    temporary2::Gaugefields_4D_nowing,
)
    reference = _require_configuration(fields)
    _require_compatible_fields(temporary1, reference)
    _require_compatible_fields(temporary2, reference)
    substitute_U!(temporary1, fields[4])
    old_product = temporary1
    new_product = temporary2
    for time_offset in 1:(reference.NT - 1)
        shifted_time_links = shift_U(fields[4], (0, 0, 0, time_offset))
        mul_skiplastindex!(new_product, old_product, shifted_time_links)
        old_product, new_product = new_product, old_product
    end
    spatial_volume = reference.NX * reference.NY * reference.NZ
    return partial_tr(old_product, 4) / (reference.NC * spatial_volume)
end

function calculate_Polyakov_loop(fields::Vector)
    reference = _require_configuration(fields)
    if reference.NC == 2
        total = 0.0 + 0.0im
        for z in 1:reference.NZ
            for y in 1:reference.NY
                for x in 1:reference.NX
                    product11 = 1.0 + 0.0im
                    product12 = 0.0 + 0.0im
                    product21 = 0.0 + 0.0im
                    product22 = 1.0 + 0.0im
                    for t in 1:reference.NT
                        link11 = fields[4][1, 1, x, y, z, t]
                        link12 = fields[4][1, 2, x, y, z, t]
                        link21 = fields[4][2, 1, x, y, z, t]
                        link22 = fields[4][2, 2, x, y, z, t]
                        next11 = product11 * link11 + product12 * link21
                        next12 = product11 * link12 + product12 * link22
                        next21 = product21 * link11 + product22 * link21
                        next22 = product21 * link12 + product22 * link22
                        product11 = next11
                        product12 = next12
                        product21 = next21
                        product22 = next22
                    end
                    total += product11 + product22
                end
            end
        end
        spatial_volume = reference.NX * reference.NY * reference.NZ
        return total / (2 * spatial_volume)
    end

    total = 0.0 + 0.0im
    for z in 1:reference.NZ
        for y in 1:reference.NY
            for x in 1:reference.NX
                product11 = 1.0 + 0.0im
                product12 = 0.0 + 0.0im
                product13 = 0.0 + 0.0im
                product21 = 0.0 + 0.0im
                product22 = 1.0 + 0.0im
                product23 = 0.0 + 0.0im
                product31 = 0.0 + 0.0im
                product32 = 0.0 + 0.0im
                product33 = 1.0 + 0.0im
                for t in 1:reference.NT
                    link11 = fields[4][1, 1, x, y, z, t]
                    link12 = fields[4][1, 2, x, y, z, t]
                    link13 = fields[4][1, 3, x, y, z, t]
                    link21 = fields[4][2, 1, x, y, z, t]
                    link22 = fields[4][2, 2, x, y, z, t]
                    link23 = fields[4][2, 3, x, y, z, t]
                    link31 = fields[4][3, 1, x, y, z, t]
                    link32 = fields[4][3, 2, x, y, z, t]
                    link33 = fields[4][3, 3, x, y, z, t]
                    next11 = product11 * link11 + product12 * link21 + product13 * link31
                    next12 = product11 * link12 + product12 * link22 + product13 * link32
                    next13 = product11 * link13 + product12 * link23 + product13 * link33
                    next21 = product21 * link11 + product22 * link21 + product23 * link31
                    next22 = product21 * link12 + product22 * link22 + product23 * link32
                    next23 = product21 * link13 + product22 * link23 + product23 * link33
                    next31 = product31 * link11 + product32 * link21 + product33 * link31
                    next32 = product31 * link12 + product32 * link22 + product33 * link32
                    next33 = product31 * link13 + product32 * link23 + product33 * link33
                    product11 = next11
                    product12 = next12
                    product13 = next13
                    product21 = next21
                    product22 = next22
                    product23 = next23
                    product31 = next31
                    product32 = next32
                    product33 = next33
                end
                total += product11 + product22 + product33
            end
        end
    end
    spatial_volume = reference.NX * reference.NY * reference.NZ
    return total / (3 * spatial_volume)
end

function _local_plaquette_energy_unchecked(fields, reference, x, y, z, t)
    total = 0.0
    for mu in 1:3
        for nu in (mu + 1):4
            total += 1.0 -
                     real(_plaquette_site_unchecked(fields, reference, mu, nu, x, y, z, t)) /
                     reference.NC
        end
    end
    return total
end

function local_plaquette_energy(fields::Vector, x, y, z, t)
    reference = _require_configuration(fields)
    return _local_plaquette_energy_unchecked(fields, reference, x, y, z, t)
end

function _plane_axes(plane)
    name = lowercase(String(plane))
    if name == "xy"
        return 1, 2, 3, 4
    elseif name == "xz"
        return 1, 3, 2, 4
    elseif name == "xt"
        return 1, 4, 2, 3
    elseif name == "yz"
        return 2, 3, 1, 4
    elseif name == "yt"
        return 2, 4, 1, 3
    elseif name == "zt"
        return 3, 4, 1, 2
    end
    throw(ArgumentError("plane must be one of xy, xz, xt, yz, yt, or zt"))
end

function _lattice_extents(reference)
    return (reference.NX, reference.NY, reference.NZ, reference.NT)
end

function slice_shape(fields::Vector, plane)
    reference = _require_configuration(fields)
    first_axis, second_axis, _, _ = _plane_axes(plane)
    extents = _lattice_extents(reference)
    return extents[first_axis], extents[second_axis]
end

function _validated_slice(slice, first_fixed_axis, second_fixed_axis, extents)
    if !(slice isa Tuple) || length(slice) != 2
        throw(ArgumentError("slice must be a tuple containing two fixed coordinates"))
    end
    first_coordinate = slice[1]
    second_coordinate = slice[2]
    if !(first_coordinate isa Integer) || !(second_coordinate isa Integer)
        throw(ArgumentError("slice coordinates must be integers"))
    end
    if first_coordinate < 1 || first_coordinate > extents[first_fixed_axis] ||
       second_coordinate < 1 || second_coordinate > extents[second_fixed_axis]
        throw(BoundsError(extents, slice))
    end
    return Int(first_coordinate), Int(second_coordinate)
end

function local_plaquette_energy!(output::AbstractVector, fields::Vector, plane, slice)
    reference = _require_configuration(fields)
    first_axis, second_axis, first_fixed_axis, second_fixed_axis = _plane_axes(plane)
    extents = _lattice_extents(reference)
    width = extents[first_axis]
    height = extents[second_axis]
    if length(output) != width * height
        throw(DimensionMismatch("slice output length must equal width × height"))
    end
    first_fixed, second_fixed =
        _validated_slice(slice, first_fixed_axis, second_fixed_axis, extents)

    for second_coordinate in 1:height
        for first_coordinate in 1:width
            coordinates = [1, 1, 1, 1]
            coordinates[first_axis] = first_coordinate
            coordinates[second_axis] = second_coordinate
            coordinates[first_fixed_axis] = first_fixed
            coordinates[second_fixed_axis] = second_fixed
            output[(second_coordinate - 1) * width + first_coordinate] =
                _local_plaquette_energy_unchecked(
                    fields,
                    reference,
                    coordinates[1],
                    coordinates[2],
                    coordinates[3],
                    coordinates[4],
                )
        end
    end
    return output
end

function local_plaquette_energy!(output::AbstractVector, fields::Vector, plane, slice::Integer)
    return local_plaquette_energy!(output, fields, plane, (slice, slice))
end

function local_slice_result(fields::Vector, plane, slice)
    width, height = slice_shape(fields, plane)
    output = zeros(Float64, width * height)
    local_plaquette_energy!(output, fields, plane, slice)
    result = Vector{Float64}(undef, 2 + length(output))
    result[1] = width
    result[2] = height
    for index in 1:length(output)
        result[index + 2] = output[index]
    end
    return result
end
