# BEGIN src/metropolis.jl
using Random

abstract type AbstractGaugeUpdater end

struct MetropolisUpdater <: AbstractGaugeUpdater
    beta::Float64
    epsilon::Float64

    function MetropolisUpdater(beta::Real, epsilon::Real)
        beta_value = Float64(beta)
        epsilon_value = Float64(epsilon)
        if !isfinite(beta_value) || beta_value < 0.0
            throw(ArgumentError("beta must be finite and nonnegative"))
        end
        if !isfinite(epsilon_value) || epsilon_value <= 0.0 || epsilon_value > 1.0
            throw(ArgumentError("epsilon must satisfy 0 < epsilon <= 1"))
        end
        return new(beta_value, epsilon_value)
    end
end

struct MetropolisWorkspace
    su2::Matrix{ComplexF64}
    embedded::Matrix{ComplexF64}
    old_link::Matrix{ComplexF64}
    proposed_link::Matrix{ComplexF64}
    staple::Matrix{ComplexF64}
    forward::Matrix{ComplexF64}
    backward::Matrix{ComplexF64}
end

function MetropolisWorkspace(nc::Integer=3)
    color_count = _validated_color_count(nc)
    return MetropolisWorkspace(
        zeros(ComplexF64, 2, 2),
        zeros(ComplexF64, color_count, color_count),
        zeros(ComplexF64, color_count, color_count),
        zeros(ComplexF64, color_count, color_count),
        zeros(ComplexF64, color_count, color_count),
        zeros(ComplexF64, color_count, color_count),
        zeros(ComplexF64, color_count, color_count),
    )
end

struct MetropolisLinkResult
    accepted::Bool
    delta_action::Float64
end

struct MetropolisSweepResult
    accepted::Int64
    offered::Int64
    acceptance_rate::Float64
end

struct MetropolisHistory
    plaquette::Vector{Float64}
    polyakov::Vector{ComplexF64}
    acceptance::Vector{Float64}
    accepted::Int64
    offered::Int64
end

function _require_matrix_shape(matrix::AbstractMatrix, rows, columns, name)
    if size(matrix) != (rows, columns)
        throw(DimensionMismatch("$name must have shape $rows×$columns"))
    end
    return nothing
end

function make_near_identity_su2!(
    proposal::AbstractMatrix,
    a1::Real,
    a2::Real,
    a3::Real,
)
    _require_matrix_shape(proposal, 2, 2, "SU(2) proposal")
    radius_squared = Float64(a1)^2 + Float64(a2)^2 + Float64(a3)^2
    if !isfinite(radius_squared) || radius_squared > 1.0
        throw(ArgumentError("proposal vector must satisfy |a| <= 1"))
    end
    a0 = sqrt(max(0.0, 1.0 - radius_squared))
    proposal[1, 1] = a0 + im * a3
    proposal[1, 2] = a2 + im * a1
    proposal[2, 1] = -a2 + im * a1
    proposal[2, 2] = a0 - im * a3
    return proposal
end

function _random_uniform(rng)
    if rng === nothing
        return rand()
    elseif rng isa Vector{Int64}
        return web_rand!(rng)
    end
    return rand(rng)
end

function make_near_identity_su2!(proposal::AbstractMatrix, epsilon::Real, rng)
    epsilon_value = Float64(epsilon)
    if !isfinite(epsilon_value) || epsilon_value <= 0.0 || epsilon_value > 1.0
        throw(ArgumentError("epsilon must satisfy 0 < epsilon <= 1"))
    end
    while true
        a1 = epsilon_value * (2.0 * _random_uniform(rng) - 1.0)
        a2 = epsilon_value * (2.0 * _random_uniform(rng) - 1.0)
        a3 = epsilon_value * (2.0 * _random_uniform(rng) - 1.0)
        if a1^2 + a2^2 + a3^2 < epsilon_value^2
            return make_near_identity_su2!(proposal, a1, a2, a3)
        end
    end
end

make_near_identity_su2!(proposal::AbstractMatrix, epsilon::Real) =
    make_near_identity_su2!(proposal, epsilon, nothing)

function _color_pair(pair::Integer)
    if pair == 1
        return 1, 2
    elseif pair == 2
        return 2, 3
    elseif pair == 3
        return 1, 3
    end
    throw(ArgumentError("SU(3) subgroup pair must be 1, 2, or 3"))
end

function embed_su2_in_su3!(embedded::AbstractMatrix, proposal::AbstractMatrix, pair::Integer)
    _require_matrix_shape(embedded, 3, 3, "embedded proposal")
    _require_matrix_shape(proposal, 2, 2, "SU(2) proposal")
    first_color, second_color = _color_pair(pair)
    fill!(embedded, 0.0 + 0.0im)
    for color in 1:3
        embedded[color, color] = 1.0 + 0.0im
    end
    embedded[first_color, first_color] = proposal[1, 1]
    embedded[first_color, second_color] = proposal[1, 2]
    embedded[second_color, first_color] = proposal[2, 1]
    embedded[second_color, second_color] = proposal[2, 2]
    return embedded
end

function _small_matrix_multiply!(output, left, right, nc)
    for j in 1:nc
        for i in 1:nc
            value = 0.0 + 0.0im
            for k in 1:nc
                value += left[i, k] * right[k, j]
            end
            output[i, j] = value
        end
    end
    return output
end

function propose_link_su3!(
    proposed_link::AbstractMatrix,
    old_link::AbstractMatrix,
    su2_proposal::AbstractMatrix,
    pair::Integer,
    embedded::AbstractMatrix,
)
    _require_matrix_shape(proposed_link, 3, 3, "proposed link")
    _require_matrix_shape(old_link, 3, 3, "old link")
    embed_su2_in_su3!(embedded, su2_proposal, pair)
    return _small_matrix_multiply!(proposed_link, embedded, old_link, 3)
end

function propose_link_su3!(proposed_link, old_link, su2_proposal, pair::Integer)
    embedded = zeros(ComplexF64, 3, 3)
    return propose_link_su3!(proposed_link, old_link, su2_proposal, pair, embedded)
end

function _copy_link_to_matrix!(matrix, field, x, y, z, t)
    for j in 1:field.NC
        for i in 1:field.NC
            matrix[i, j] = field[i, j, x, y, z, t]
        end
    end
    return matrix
end

function _write_matrix_to_link!(field, matrix, x, y, z, t)
    for j in 1:field.NC
        for i in 1:field.NC
            field[i, j, x, y, z, t] = matrix[i, j]
        end
    end
    return field
end

function local_wilson_staple_site!(
    staple::AbstractMatrix,
    fields::Vector,
    mu::Integer,
    x,
    y,
    z,
    t,
    forward::AbstractMatrix,
    backward::AbstractMatrix,
)
    reference = _require_configuration(fields)
    nc = reference.NC
    _require_matrix_shape(staple, nc, nc, "Wilson staple")
    _require_matrix_shape(forward, nc, nc, "forward staple workspace")
    _require_matrix_shape(backward, nc, nc, "backward staple workspace")
    fill!(staple, 0.0 + 0.0im)
    for nu in 1:4
        if nu == mu
            continue
        end
        forward_staple_site!(forward, fields, mu, nu, x, y, z, t)
        backward_staple_site!(backward, fields, mu, nu, x, y, z, t)
        for j in 1:nc
            for i in 1:nc
                staple[i, j] += forward[i, j] + backward[i, j]
            end
        end
    end
    return staple
end

function local_wilson_staple_site!(staple, fields, mu, x, y, z, t)
    reference = _require_configuration(fields)
    forward = zeros(ComplexF64, reference.NC, reference.NC)
    backward = zeros(ComplexF64, reference.NC, reference.NC)
    return local_wilson_staple_site!(staple, fields, mu, x, y, z, t, forward, backward)
end

function local_action_from_staple(link::AbstractMatrix, staple::AbstractMatrix, beta::Real)
    rows, columns = size(link)
    if rows != columns || size(staple) != size(link)
        throw(DimensionMismatch("link and staple must be square matrices of the same shape"))
    end
    trace_product = 0.0 + 0.0im
    for i in 1:rows
        for j in 1:rows
            trace_product += link[i, j] * staple[j, i]
        end
    end
    return -(Float64(beta) / rows) * real(trace_product)
end

function wilson_action(fields::Vector, beta::Real)
    reference = _require_configuration(fields)
    return Float64(beta) * (6.0 * reference.NV - calculate_Plaquette(fields) / reference.NC)
end

function _affected_plaquette_sum_unchecked(fields, reference, mu, x, y, z, t)
    total = 0.0
    for nu in 1:4
        if nu == mu
            continue
        end
        first_direction = min(mu, nu)
        second_direction = max(mu, nu)
        total += real(
            _plaquette_site_unchecked(
                fields,
                reference,
                first_direction,
                second_direction,
                x,
                y,
                z,
                t,
            ),
        )
        shifted_x, shifted_y, shifted_z, shifted_t =
            _shifted_coordinates(x, y, z, t, nu, -1, reference)
        if shifted_x != x || shifted_y != y || shifted_z != z || shifted_t != t
            total += real(
                _plaquette_site_unchecked(
                    fields,
                    reference,
                    first_direction,
                    second_direction,
                    shifted_x,
                    shifted_y,
                    shifted_z,
                    shifted_t,
                ),
            )
        end
    end
    return total
end

function metropolis_accept(delta_action::Real, uniform_draw::Real)
    delta_value = Float64(delta_action)
    draw = Float64(uniform_draw)
    if !isfinite(delta_value)
        throw(ArgumentError("delta action must be finite"))
    end
    if !isfinite(draw) || draw < 0.0 || draw >= 1.0
        throw(ArgumentError("uniform draw must satisfy 0 <= draw < 1"))
    end
    return delta_value <= 0.0 || draw < exp(-delta_value)
end

function _fixed_link_result!(
    fields,
    updater,
    mu,
    x,
    y,
    z,
    t,
    workspace,
    su2_proposal,
    pair,
    uniform_draw,
)
    reference = _require_configuration(fields)
    nc = reference.NC
    _copy_link_to_matrix!(workspace.old_link, fields[mu], x, y, z, t)
    if nc == 2
        _small_matrix_multiply!(
            workspace.proposed_link,
            su2_proposal,
            workspace.old_link,
            2,
        )
    else
        propose_link_su3!(
            workspace.proposed_link,
            workspace.old_link,
            su2_proposal,
            pair,
            workspace.embedded,
        )
    end

    degenerate = reference.NX == 1 || reference.NY == 1 || reference.NZ == 1 || reference.NT == 1
    if degenerate
        old_plaquette_sum =
            _affected_plaquette_sum_unchecked(fields, reference, mu, x, y, z, t)
        _write_matrix_to_link!(fields[mu], workspace.proposed_link, x, y, z, t)
        new_plaquette_sum =
            _affected_plaquette_sum_unchecked(fields, reference, mu, x, y, z, t)
        delta_action =
            -(Float64(updater.beta) / nc) * (new_plaquette_sum - old_plaquette_sum)
        accepted = metropolis_accept(delta_action, uniform_draw)
        if !accepted
            _write_matrix_to_link!(fields[mu], workspace.old_link, x, y, z, t)
        end
        return MetropolisLinkResult(accepted, delta_action)
    end

    local_wilson_staple_site!(
        workspace.staple,
        fields,
        mu,
        x,
        y,
        z,
        t,
        workspace.forward,
        workspace.backward,
    )
    old_action = local_action_from_staple(workspace.old_link, workspace.staple, updater.beta)
    new_action = local_action_from_staple(workspace.proposed_link, workspace.staple, updater.beta)
    delta_action = new_action - old_action
    accepted = metropolis_accept(delta_action, uniform_draw)
    if accepted
        _write_matrix_to_link!(fields[mu], workspace.proposed_link, x, y, z, t)
    end
    return MetropolisLinkResult(accepted, delta_action)
end

function metropolis_link_fixed!(
    fields::Vector,
    updater::MetropolisUpdater,
    mu::Integer,
    x,
    y,
    z,
    t,
    workspace::MetropolisWorkspace,
    su2_proposal::AbstractMatrix,
    pair::Integer,
    uniform_draw::Real,
)
    return _fixed_link_result!(
        fields,
        updater,
        mu,
        x,
        y,
        z,
        t,
        workspace,
        su2_proposal,
        pair,
        uniform_draw,
    )
end

function metropolis_link!(
    fields::Vector,
    updater::MetropolisUpdater,
    mu::Integer,
    x,
    y,
    z,
    t,
    workspace::MetropolisWorkspace,
    rng,
    pair::Integer,
)
    make_near_identity_su2!(workspace.su2, updater.epsilon, rng)
    uniform_draw = _random_uniform(rng)
    return _fixed_link_result!(
        fields,
        updater,
        mu,
        x,
        y,
        z,
        t,
        workspace,
        workspace.su2,
        pair,
        uniform_draw,
    )
end

function metropolis_link!(fields, updater, mu, x, y, z, t; rng=nothing, pair=1)
    reference = _require_configuration(fields)
    return metropolis_link!(
        fields,
        updater,
        mu,
        x,
        y,
        z,
        t,
        MetropolisWorkspace(reference.NC),
        rng,
        pair,
    )
end

"""
    sweep!(fields, updater; rng=nothing, workspace=MetropolisWorkspace())

Offer one update to every link in site-major order: `t`, `z`, `y`, `x`, then
direction `mu`. SU(2) subgroups cycle `(1,2)`, `(2,3)`, `(1,3)`.
"""
function sweep!(
    fields::Vector,
    updater::MetropolisUpdater;
    rng=nothing,
    workspace=nothing,
)
    reference = _require_configuration(fields)
    active_workspace = workspace === nothing ? MetropolisWorkspace(reference.NC) : workspace
    accepted = 0
    offered = 0
    for t in 1:reference.NT
        for z in 1:reference.NZ
            for y in 1:reference.NY
                for x in 1:reference.NX
                    for mu in 1:4
                        offered += 1
                        pair = reference.NC == 2 ? 1 : mod(offered - 1, 3) + 1
                        result = metropolis_link!(
                            fields,
                            updater,
                            mu,
                            x,
                            y,
                            z,
                            t,
                            active_workspace,
                            rng,
                            pair,
                        )
                        accepted += ifelse(result.accepted, 1, 0)
                    end
                end
            end
        end
    end
    return MetropolisSweepResult(accepted, offered, accepted / offered)
end

function run_sweeps!(fields::Vector, updater::MetropolisUpdater, number_of_sweeps::Integer; rng=nothing)
    if number_of_sweeps < 0
        throw(ArgumentError("number_of_sweeps must be nonnegative"))
    end
    plaquette_history = Vector{Float64}(undef, number_of_sweeps)
    polyakov_history = Vector{ComplexF64}(undef, number_of_sweeps)
    acceptance_history = Vector{Float64}(undef, number_of_sweeps)
    reference = _require_configuration(fields)
    workspace = MetropolisWorkspace(reference.NC)
    total_accepted = 0
    total_offered = 0
    for sweep_index in 1:number_of_sweeps
        result = sweep!(fields, updater; rng=rng, workspace=workspace)
        total_accepted += result.accepted
        total_offered += result.offered
        plaquette_history[sweep_index] = normalized_plaquette(fields)
        polyakov_history[sweep_index] = calculate_Polyakov_loop(fields)
        acceptance_history[sweep_index] = result.acceptance_rate
    end
    return MetropolisHistory(
        plaquette_history,
        polyakov_history,
        acceptance_history,
        total_accepted,
        total_offered,
    )
end
# END src/metropolis.jl

# BEGIN src/webapi.jl
const WEB_RESULT_SCHEMA_VERSION = 2.0
const WEB_RESULT_HEADER_LENGTH = 11
const WEB_CHUNK_SCHEMA_VERSION = 1.0
const WEB_CHUNK_HEADER_LENGTH = 19
const _WEB_MAX_LATTICE_SIZE = 8
const _WEB_MAX_SWEEPS = 1000
const _WEB_MAX_SEED = 9007199254740991

"""
    WebObservables

Observables measured on one completed configuration. The slice values use
row-major display order: the first plane coordinate changes fastest.
"""
struct WebObservables
    plaquette::Float64
    polyakov::ComplexF64
    slice_width::Int64
    slice_height::Int64
    slice_values::Vector{Float64}
end

"""
    WebSimulationResult

Internal result of one browser-oriented simulation job. Convert it to the
stable flat numeric contract with [`encode_web_result`](@ref).
"""
struct WebSimulationResult
    sweeps::Int64
    plaquette_history::Vector{Float64}
    polyakov_history::Vector{ComplexF64}
    acceptance_history::Vector{Float64}
    accepted::Int64
    offered::Int64
    observables::WebObservables
    slice_frames::Vector{Float64}
end

struct WebChunkResult
    nc::Int64
    nx::Int64
    ny::Int64
    nz::Int64
    nt::Int64
    completed_sweeps::Int64
    simulation::WebSimulationResult
    rng_state::Int64
    configuration::Vector{Float64}
end

mutable struct WebGenericSession{F,W}
    nc::Int64
    nx::Int64
    ny::Int64
    nz::Int64
    nt::Int64
    fields::F
    updater::MetropolisUpdater
    rng_state::Vector{Int64}
    workspace::W
    completed_sweeps::Int64
    plane::String
    slice::Tuple{Int64,Int64}
    width::Int64
    height::Int64
    slice_buffer::Vector{Float64}
end

function _validated_web_integer(value, name, minimum, maximum)
    if !(value isa Integer)
        throw(ArgumentError("$name must be an integer"))
    end
    if value < minimum || value > maximum
        throw(ArgumentError("$name must be in $minimum:$maximum"))
    end
    return Int64(value)
end

function _validated_web_seed(seed)
    if !(seed isa Integer)
        throw(ArgumentError("seed must be an integer"))
    end
    if seed < 0 || seed > _WEB_MAX_SEED
        throw(ArgumentError("seed must be in 0:$_WEB_MAX_SEED"))
    end
    return Int64(seed)
end

function _validated_web_condition(condition)
    condition_name = lowercase(String(condition))
    if condition_name != "cold" && condition_name != "hot"
        throw(ArgumentError("condition must be \"cold\" or \"hot\""))
    end
    return condition_name
end

function web_configuration_state_length(nc, nx, ny, nz, nt)
    color_count = _validated_color_count(nc)
    nx_value = _validated_web_integer(nx, "nx", 1, _WEB_MAX_LATTICE_SIZE)
    ny_value = _validated_web_integer(ny, "ny", 1, _WEB_MAX_LATTICE_SIZE)
    nz_value = _validated_web_integer(nz, "nz", 1, _WEB_MAX_LATTICE_SIZE)
    nt_value = _validated_web_integer(nt, "nt", 1, _WEB_MAX_LATTICE_SIZE)
    return 2 * 4 * color_count * color_count * nx_value * ny_value * nz_value * nt_value
end

function encode_web_configuration(fields::Vector)
    reference = _require_configuration(fields)
    output = Vector{Float64}(
        undef,
        web_configuration_state_length(
            reference.NC,
            reference.NX,
            reference.NY,
            reference.NZ,
            reference.NT,
        ),
    )
    cursor = 0
    for mu in 1:4
        field = fields[mu]
        for t in 1:reference.NT
            for z in 1:reference.NZ
                for y in 1:reference.NY
                    for x in 1:reference.NX
                        for j in 1:reference.NC
                            for i in 1:reference.NC
                                value = field[i, j, x, y, z, t]
                                output[cursor + 1] = real(value)
                                output[cursor + 2] = imag(value)
                                cursor += 2
                            end
                        end
                    end
                end
            end
        end
    end
    return output
end

function decode_web_configuration(nc, nx, ny, nz, nt, state::AbstractVector)
    expected_length = web_configuration_state_length(nc, nx, ny, nz, nt)
    if length(state) != expected_length
        throw(DimensionMismatch("configuration state length must equal $expected_length"))
    end
    fields = Initialize_4DGaugefields(nc, 0, nx, ny, nz, nt; condition="cold")
    cursor = 0
    for mu in 1:4
        field = fields[mu]
        for t in 1:field.NT
            for z in 1:field.NZ
                for y in 1:field.NY
                    for x in 1:field.NX
                        for j in 1:field.NC
                            for i in 1:field.NC
                                real_part = Float64(state[cursor + 1])
                                imaginary_part = Float64(state[cursor + 2])
                                if !isfinite(real_part) || !isfinite(imaginary_part)
                                    throw(ArgumentError("configuration state must be finite"))
                                end
                                field[i, j, x, y, z, t] = ComplexF64(real_part, imaginary_part)
                                cursor += 2
                            end
                        end
                    end
                end
            end
        end
    end
    return fields
end

function _initialize_web_configuration(nc, nx, ny, nz, nt, condition, rng_state)
    fields = Initialize_4DGaugefields(nc, 0, nx, ny, nz, nt; condition="cold")
    if condition == "cold"
        return fields
    end
    matrix = zeros(ComplexF64, nc, nc)
    for mu in 1:4
        field = fields[mu]
        for t in 1:nt
            for z in 1:nz
                for y in 1:ny
                    for x in 1:nx
                        for j in 1:nc
                            for i in 1:nc
                                real_part, imaginary_part = web_standard_normal_pair!(rng_state)
                                matrix[i, j] = ComplexF64(real_part, imaginary_part)
                            end
                        end
                        normalizeN!(matrix)
                        for j in 1:nc
                            for i in 1:nc
                                field[i, j, x, y, z, t] = matrix[i, j]
                            end
                        end
                    end
                end
            end
        end
    end
    return fields
end

"""
    run_observables_on_configuration(fields; plane="xy", slice=(1, 1))

Measure the final normalized plaquette, complex Polyakov loop, and one local
plaquette-energy slice without exposing gauge-field objects to JavaScript.
"""
function run_observables_on_configuration(fields; plane="xy", slice=(1, 1))
    reference = _require_configuration(fields)
    width, height = slice_shape(fields, plane)
    slice_values = zeros(Float64, width * height)
    local_plaquette_energy!(slice_values, fields, plane, slice)
    return WebObservables(
        normalized_plaquette(fields),
        calculate_Polyakov_loop(fields),
        Int64(width),
        Int64(height),
        slice_values,
    )
end

function _copy_slice_frame!(frames, frame_index, frame_size, fields, plane, slice, buffer)
    local_plaquette_energy!(buffer, fields, plane, slice)
    offset = (frame_index - 1) * frame_size
    for index in 1:frame_size
        frames[offset + index] = buffer[index]
    end
    return frames
end

"""
    run_simulation(nx, ny, nz, nt, beta, number_of_sweeps, seed; kwargs...)
    run_simulation(lattice_size, beta, number_of_sweeps, seed; kwargs...)

Run a complete SU(3) Metropolis job in one Julia call. The public v0.1 path is
serial and bounded to avoid accidental unbounded browser allocations. The
four-extent method supports anisotropic lattices; the scalar method is the
backward-compatible cubic shortcut.
"""
function run_simulation(
    nx,
    ny,
    nz,
    nt,
    beta,
    number_of_sweeps,
    seed;
    epsilon=0.2,
    condition="cold",
    plane="xy",
    slice=(1, 1),
)
    nx_value = _validated_web_integer(nx, "nx", 1, _WEB_MAX_LATTICE_SIZE)
    ny_value = _validated_web_integer(ny, "ny", 1, _WEB_MAX_LATTICE_SIZE)
    nz_value = _validated_web_integer(nz, "nz", 1, _WEB_MAX_LATTICE_SIZE)
    nt_value = _validated_web_integer(nt, "nt", 1, _WEB_MAX_LATTICE_SIZE)
    sweep_count =
        _validated_web_integer(number_of_sweeps, "number_of_sweeps", 0, _WEB_MAX_SWEEPS)
    seed_value = _validated_web_seed(seed)
    condition_name = _validated_web_condition(condition)
    updater = MetropolisUpdater(beta, epsilon)

    Random.seed!(seed_value)
    fields = Initialize_4DGaugefields(
        3,
        0,
        nx_value,
        ny_value,
        nz_value,
        nt_value;
        condition=condition_name,
    )
    width, height = slice_shape(fields, plane)
    frame_size = width * height
    slice_frames = Vector{Float64}(undef, (sweep_count + 1) * frame_size)
    slice_buffer = zeros(Float64, frame_size)
    _copy_slice_frame!(slice_frames, 1, frame_size, fields, plane, slice, slice_buffer)

    plaquette_history = Vector{Float64}(undef, sweep_count)
    polyakov_history = Vector{ComplexF64}(undef, sweep_count)
    acceptance_history = Vector{Float64}(undef, sweep_count)
    workspace = MetropolisWorkspace()
    total_accepted = 0
    total_offered = 0
    for sweep_index in 1:sweep_count
        update_result = sweep!(fields, updater; workspace=workspace)
        total_accepted += update_result.accepted
        total_offered += update_result.offered
        plaquette_history[sweep_index] = normalized_plaquette(fields)
        polyakov_history[sweep_index] = calculate_Polyakov_loop(fields)
        acceptance_history[sweep_index] = update_result.acceptance_rate
        _copy_slice_frame!(
            slice_frames,
            sweep_index + 1,
            frame_size,
            fields,
            plane,
            slice,
            slice_buffer,
        )
    end

    history = MetropolisHistory(
        plaquette_history,
        polyakov_history,
        acceptance_history,
        total_accepted,
        total_offered,
    )
    final_plaquette = sweep_count == 0 ? normalized_plaquette(fields) : plaquette_history[sweep_count]
    final_polyakov =
        sweep_count == 0 ? calculate_Polyakov_loop(fields) : polyakov_history[sweep_count]
    final_slice = copy(slice_buffer)
    observables = WebObservables(
        final_plaquette,
        final_polyakov,
        Int64(width),
        Int64(height),
        final_slice,
    )
    return WebSimulationResult(
        sweep_count,
        history.plaquette,
        history.polyakov,
        history.acceptance,
        history.accepted,
        history.offered,
        observables,
        slice_frames,
    )
end

function run_simulation(
    lattice_size,
    beta,
    number_of_sweeps,
    seed;
    epsilon=0.2,
    condition="cold",
    plane="xy",
    slice=(1, 1),
)
    return run_simulation(
        lattice_size,
        lattice_size,
        lattice_size,
        lattice_size,
        beta,
        number_of_sweeps,
        seed;
        epsilon=epsilon,
        condition=condition,
        plane=plane,
        slice=slice,
    )
end

function _validate_web_result(result::WebSimulationResult)
    sweep_count = result.sweeps
    if sweep_count < 0 ||
       length(result.plaquette_history) != sweep_count ||
       length(result.polyakov_history) != sweep_count ||
       length(result.acceptance_history) != sweep_count
        throw(ArgumentError("history lengths must equal the sweep count"))
    end
    if result.accepted < 0 || result.offered < 0 || result.accepted > result.offered
        throw(ArgumentError("accepted/offered counts are inconsistent"))
    end
    observables = result.observables
    frame_count = sweep_count + 1
    frame_size = observables.slice_width * observables.slice_height
    if observables.slice_width <= 0 || observables.slice_height <= 0 ||
       length(observables.slice_values) !=
       frame_size ||
       length(result.slice_frames) != frame_count * frame_size
        throw(ArgumentError("slice metadata and values are inconsistent"))
    end
    final_offset = (frame_count - 1) * frame_size
    for index in 1:frame_size
        if result.slice_frames[final_offset + index] != observables.slice_values[index]
            throw(ArgumentError("the final slice frame must match the final observables"))
        end
    end
    return nothing
end

"""
    encode_web_result(result)

Encode a simulation result as a `Vector{Float64}`. Schema version 2 layout:

```text
[schema, sweeps, final_plaquette, final_polyakov_re, final_polyakov_im,
 overall_acceptance, accepted, offered, slice_width, slice_height, frame_count,
 plaquette_history...,
 polyakov_real_history...,
 polyakov_imag_history...,
 acceptance_history...,
 slice_frames...]
```
"""
function encode_web_result(result::WebSimulationResult)
    _validate_web_result(result)
    sweep_count = result.sweeps
    observables = result.observables
    output_length =
        WEB_RESULT_HEADER_LENGTH + 4 * sweep_count + length(result.slice_frames)
    output = Vector{Float64}(undef, output_length)

    output[1] = WEB_RESULT_SCHEMA_VERSION
    output[2] = sweep_count
    output[3] = observables.plaquette
    output[4] = real(observables.polyakov)
    output[5] = imag(observables.polyakov)
    output[6] = result.offered == 0 ? 0.0 : result.accepted / result.offered
    output[7] = result.accepted
    output[8] = result.offered
    output[9] = observables.slice_width
    output[10] = observables.slice_height
    output[11] = sweep_count + 1

    offset = WEB_RESULT_HEADER_LENGTH
    for index in 1:sweep_count
        output[offset + index] = result.plaquette_history[index]
    end
    offset += sweep_count
    for index in 1:sweep_count
        output[offset + index] = real(result.polyakov_history[index])
    end
    offset += sweep_count
    for index in 1:sweep_count
        output[offset + index] = imag(result.polyakov_history[index])
    end
    offset += sweep_count
    for index in 1:sweep_count
        output[offset + index] = result.acceptance_history[index]
    end
    offset += sweep_count
    for index in 1:length(result.slice_frames)
        output[offset + index] = result.slice_frames[index]
    end
    return output
end

function run_simulation_chunk(
    nc,
    nx,
    ny,
    nz,
    nt,
    beta,
    chunk_sweeps,
    seed_or_rng_state,
    completed_sweeps,
    configuration::AbstractVector;
    epsilon=0.2,
    condition="cold",
    plane="xy",
    slice=(1, 1),
)
    color_count = _validated_color_count(nc)
    nx_value = _validated_web_integer(nx, "nx", 1, _WEB_MAX_LATTICE_SIZE)
    ny_value = _validated_web_integer(ny, "ny", 1, _WEB_MAX_LATTICE_SIZE)
    nz_value = _validated_web_integer(nz, "nz", 1, _WEB_MAX_LATTICE_SIZE)
    nt_value = _validated_web_integer(nt, "nt", 1, _WEB_MAX_LATTICE_SIZE)
    sweep_count = _validated_web_integer(chunk_sweeps, "chunk_sweeps", 0, _WEB_MAX_SWEEPS)
    completed = _validated_web_integer(completed_sweeps, "completed_sweeps", 0, _WEB_MAX_SWEEPS)
    if completed + sweep_count > _WEB_MAX_SWEEPS
        throw(ArgumentError("completed_sweeps + chunk_sweeps must not exceed $_WEB_MAX_SWEEPS"))
    end
    condition_name = _validated_web_condition(condition)
    updater = MetropolisUpdater(beta, epsilon)

    first_chunk = isempty(configuration)
    if first_chunk && completed != 0
        throw(ArgumentError("an empty configuration requires completed_sweeps = 0"))
    end
    rng_state = if first_chunk
        web_rng_state(_validated_web_seed(seed_or_rng_state))
    else
        restore_web_rng_state(seed_or_rng_state)
    end
    fields = if first_chunk
        _initialize_web_configuration(
            color_count,
            nx_value,
            ny_value,
            nz_value,
            nt_value,
            condition_name,
            rng_state,
        )
    else
        decode_web_configuration(
            color_count,
            nx_value,
            ny_value,
            nz_value,
            nt_value,
            configuration,
        )
    end

    width, height = slice_shape(fields, plane)
    frame_size = width * height
    slice_frames = Vector{Float64}(undef, (sweep_count + 1) * frame_size)
    slice_buffer = zeros(Float64, frame_size)
    _copy_slice_frame!(slice_frames, 1, frame_size, fields, plane, slice, slice_buffer)

    plaquette_history = Vector{Float64}(undef, sweep_count)
    polyakov_history = Vector{ComplexF64}(undef, sweep_count)
    acceptance_history = Vector{Float64}(undef, sweep_count)
    workspace = MetropolisWorkspace(color_count)
    total_accepted = 0
    total_offered = 0
    for sweep_index in 1:sweep_count
        update_result = sweep!(fields, updater; rng=rng_state, workspace=workspace)
        total_accepted += update_result.accepted
        total_offered += update_result.offered
        plaquette_history[sweep_index] = normalized_plaquette(fields)
        polyakov_history[sweep_index] = calculate_Polyakov_loop(fields)
        acceptance_history[sweep_index] = update_result.acceptance_rate
        _copy_slice_frame!(
            slice_frames,
            sweep_index + 1,
            frame_size,
            fields,
            plane,
            slice,
            slice_buffer,
        )
    end

    final_plaquette = sweep_count == 0 ? normalized_plaquette(fields) : plaquette_history[sweep_count]
    final_polyakov =
        sweep_count == 0 ? calculate_Polyakov_loop(fields) : polyakov_history[sweep_count]
    final_slice = copy(slice_buffer)
    observables = WebObservables(
        final_plaquette,
        final_polyakov,
        Int64(width),
        Int64(height),
        final_slice,
    )
    simulation = WebSimulationResult(
        sweep_count,
        plaquette_history,
        polyakov_history,
        acceptance_history,
        total_accepted,
        total_offered,
        observables,
        slice_frames,
    )
    return WebChunkResult(
        color_count,
        nx_value,
        ny_value,
        nz_value,
        nt_value,
        completed + sweep_count,
        simulation,
        rng_state[1],
        encode_web_configuration(fields),
    )
end

function encode_web_chunk_result(result::WebChunkResult)
    simulation = result.simulation
    _validate_web_result(simulation)
    sweep_count = simulation.sweeps
    observables = simulation.observables
    output_length = WEB_CHUNK_HEADER_LENGTH +
                    4 * sweep_count +
                    length(simulation.slice_frames) +
                    length(result.configuration)
    output = Vector{Float64}(undef, output_length)
    output[1] = WEB_CHUNK_SCHEMA_VERSION
    output[2] = result.nc
    output[3] = result.nx
    output[4] = result.ny
    output[5] = result.nz
    output[6] = result.nt
    output[7] = sweep_count
    output[8] = result.completed_sweeps
    output[9] = observables.plaquette
    output[10] = real(observables.polyakov)
    output[11] = imag(observables.polyakov)
    output[12] = simulation.offered == 0 ? 0.0 : simulation.accepted / simulation.offered
    output[13] = simulation.accepted
    output[14] = simulation.offered
    output[15] = observables.slice_width
    output[16] = observables.slice_height
    output[17] = sweep_count + 1
    output[18] = result.rng_state
    output[19] = length(result.configuration)

    offset = WEB_CHUNK_HEADER_LENGTH
    for value in simulation.plaquette_history
        offset += 1
        output[offset] = value
    end
    for value in simulation.polyakov_history
        offset += 1
        output[offset] = real(value)
    end
    for value in simulation.polyakov_history
        offset += 1
        output[offset] = imag(value)
    end
    for value in simulation.acceptance_history
        offset += 1
        output[offset] = value
    end
    for value in simulation.slice_frames
        offset += 1
        output[offset] = value
    end
    for value in result.configuration
        offset += 1
        output[offset] = value
    end
    return output
end

function start_web_simulation_session(
    nc,
    nx,
    ny,
    nz,
    nt,
    beta,
    seed;
    epsilon=0.2,
    condition="cold",
    plane="xy",
    slice=(1, 1),
    low_precision=false,
)
    color_count = _validated_color_count(nc)
    nx_value = _validated_web_integer(nx, "nx", 1, _WEB_MAX_LATTICE_SIZE)
    ny_value = _validated_web_integer(ny, "ny", 1, _WEB_MAX_LATTICE_SIZE)
    nz_value = _validated_web_integer(nz, "nz", 1, _WEB_MAX_LATTICE_SIZE)
    nt_value = _validated_web_integer(nt, "nt", 1, _WEB_MAX_LATTICE_SIZE)
    seed_value = _validated_web_seed(seed)
    condition_name = _validated_web_condition(condition)
    updater = MetropolisUpdater(beta, epsilon)
    first_axis, second_axis, first_fixed_axis, second_fixed_axis = _plane_axes(plane)
    extents = (nx_value, ny_value, nz_value, nt_value)
    fixed_slice = _validated_slice(slice, first_fixed_axis, second_fixed_axis, extents)

    if color_count == 2 && nx_value > 1 && ny_value > 1 && nz_value > 1 && nt_value > 1
        return start_fast_su2_web_session(
            nx_value,
            ny_value,
            nz_value,
            nt_value,
            updater.beta,
            seed_value;
            epsilon=updater.epsilon,
            condition=condition_name,
            plane=plane,
            slice=fixed_slice,
            low_precision=low_precision,
        )
    end

    rng_state = web_rng_state(seed_value)
    fields = _initialize_web_configuration(
        color_count,
        nx_value,
        ny_value,
        nz_value,
        nt_value,
        condition_name,
        rng_state,
    )
    width = extents[first_axis]
    height = extents[second_axis]
    return WebGenericSession(
        color_count,
        nx_value,
        ny_value,
        nz_value,
        nt_value,
        fields,
        updater,
        rng_state,
        MetropolisWorkspace(color_count),
        0,
        String(plane),
        fixed_slice,
        Int64(width),
        Int64(height),
        zeros(Float64, width * height),
    )
end

function run_web_session_chunk!(session::WebGenericSession, chunk_sweeps)
    sweep_count = _validated_web_integer(chunk_sweeps, "chunk_sweeps", 0, _WEB_MAX_SWEEPS)
    if session.completed_sweeps + sweep_count > _WEB_MAX_SWEEPS
        throw(ArgumentError("cumulative sweep count must not exceed $_WEB_MAX_SWEEPS"))
    end
    frame_size = session.width * session.height
    frames = Vector{Float64}(undef, (sweep_count + 1) * frame_size)
    _copy_slice_frame!(
        frames,
        1,
        frame_size,
        session.fields,
        session.plane,
        session.slice,
        session.slice_buffer,
    )
    plaquette_history = Vector{Float64}(undef, sweep_count)
    polyakov_history = Vector{ComplexF64}(undef, sweep_count)
    acceptance_history = Vector{Float64}(undef, sweep_count)
    accepted_total = 0
    offered_total = 0
    for sweep_index in 1:sweep_count
        update_result = sweep!(
            session.fields,
            session.updater;
            rng=session.rng_state,
            workspace=session.workspace,
        )
        accepted_total += update_result.accepted
        offered_total += update_result.offered
        plaquette_history[sweep_index] = normalized_plaquette(session.fields)
        polyakov_history[sweep_index] = calculate_Polyakov_loop(session.fields)
        acceptance_history[sweep_index] = update_result.acceptance_rate
        _copy_slice_frame!(
            frames,
            sweep_index + 1,
            frame_size,
            session.fields,
            session.plane,
            session.slice,
            session.slice_buffer,
        )
    end
    final_plaquette =
        sweep_count == 0 ? normalized_plaquette(session.fields) : plaquette_history[sweep_count]
    final_polyakov =
        sweep_count == 0 ? calculate_Polyakov_loop(session.fields) : polyakov_history[sweep_count]
    session.completed_sweeps += sweep_count
    simulation = WebSimulationResult(
        sweep_count,
        plaquette_history,
        polyakov_history,
        acceptance_history,
        accepted_total,
        offered_total,
        WebObservables(
            final_plaquette,
            final_polyakov,
            session.width,
            session.height,
            copy(session.slice_buffer),
        ),
        frames,
    )
    output = encode_web_chunk_result(
        WebChunkResult(
            session.nc,
            session.nx,
            session.ny,
            session.nz,
            session.nt,
            session.completed_sweeps,
            simulation,
            session.rng_state[1],
            Float64[],
        ),
    )
    output[1] = 2.0
    return output
end

function run_simulation_chunk_web(
    nc,
    nx,
    ny,
    nz,
    nt,
    beta,
    chunk_sweeps,
    seed_or_rng_state,
    completed_sweeps,
    configuration::AbstractVector;
    epsilon=0.2,
    condition="cold",
    plane="xy",
    slice=(1, 1),
)
    color_count = _validated_color_count(nc)
    nx_value = _validated_web_integer(nx, "nx", 1, _WEB_MAX_LATTICE_SIZE)
    ny_value = _validated_web_integer(ny, "ny", 1, _WEB_MAX_LATTICE_SIZE)
    nz_value = _validated_web_integer(nz, "nz", 1, _WEB_MAX_LATTICE_SIZE)
    nt_value = _validated_web_integer(nt, "nt", 1, _WEB_MAX_LATTICE_SIZE)
    sweep_count = _validated_web_integer(chunk_sweeps, "chunk_sweeps", 0, _WEB_MAX_SWEEPS)
    completed = _validated_web_integer(completed_sweeps, "completed_sweeps", 0, _WEB_MAX_SWEEPS)
    if completed + sweep_count > _WEB_MAX_SWEEPS
        throw(ArgumentError("completed_sweeps + chunk_sweeps must not exceed $_WEB_MAX_SWEEPS"))
    end
    condition_name = _validated_web_condition(condition)
    updater = MetropolisUpdater(beta, epsilon)
    first_chunk = isempty(configuration)
    if first_chunk && completed != 0
        throw(ArgumentError("an empty configuration requires completed_sweeps = 0"))
    end

    if color_count == 2 && nx_value > 1 && ny_value > 1 && nz_value > 1 && nt_value > 1
        rng_value = if first_chunk
            _validated_web_seed(seed_or_rng_state)
        else
            restore_web_rng_state(seed_or_rng_state)[1]
        end
        first_axis, second_axis, first_fixed_axis, second_fixed_axis = _plane_axes(plane)
        extents = (nx_value, ny_value, nz_value, nt_value)
        fixed_slice = _validated_slice(slice, first_fixed_axis, second_fixed_axis, extents)
        return run_fast_su2_chunk_web(
            nx_value,
            ny_value,
            nz_value,
            nt_value,
            updater.beta,
            sweep_count,
            rng_value,
            completed,
            configuration;
            epsilon=updater.epsilon,
            condition=condition_name,
            plane=plane,
            slice=fixed_slice,
        )
    end

    return encode_web_chunk_result(
        run_simulation_chunk(
            color_count,
            nx_value,
            ny_value,
            nz_value,
            nt_value,
            updater.beta,
            sweep_count,
            seed_or_rng_state,
            completed,
            configuration;
            epsilon=updater.epsilon,
            condition=condition_name,
            plane=plane,
            slice=slice,
        ),
    )
end

"""
    run_simulation_web(nx, ny, nz, nt, beta, number_of_sweeps, seed; kwargs...)
    run_simulation_web(lattice_size, beta, number_of_sweeps, seed; kwargs...)

One-shot browser entrypoint that initializes, updates, measures, and returns
only the flat numeric schema accepted by `run_from_source_typed`.
"""
function run_simulation_web(
    nx,
    ny,
    nz,
    nt,
    beta,
    number_of_sweeps,
    seed;
    epsilon=0.2,
    condition="cold",
    plane="xy",
    slice=(1, 1),
)
    result = run_simulation(
        nx,
        ny,
        nz,
        nt,
        beta,
        number_of_sweeps,
        seed;
        epsilon=epsilon,
        condition=condition,
        plane=plane,
        slice=slice,
    )
    return encode_web_result(result)
end


function run_simulation_web(
    lattice_size,
    beta,
    number_of_sweeps,
    seed;
    epsilon=0.2,
    condition="cold",
    plane="xy",
    slice=(1, 1),
)
    return run_simulation_web(
        lattice_size,
        lattice_size,
        lattice_size,
        lattice_size,
        beta,
        number_of_sweeps,
        seed;
        epsilon=epsilon,
        condition=condition,
        plane=plane,
        slice=slice,
    )
end
